import{_ as t,o as a,c as s,a3 as o}from"./chunks/framework.DAK02U1-.js";const g=JSON.parse('{"title":"Releases","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Releases | clice.io"}],["meta",{"property":"og:url","content":"https://docs.clice.io/xclang/reference/releases"}],["meta",{"property":"og:image","content":"https://docs.clice.io/og.png"}],["meta",{"property":"og:image:width","content":"1200"}],["meta",{"property":"og:image:height","content":"630"}],["meta",{"property":"og:locale","content":"en_US"}],["link",{"rel":"canonical","href":"https://docs.clice.io/xclang/reference/releases"}],["link",{"rel":"alternate","hreflang":"en","href":"https://docs.clice.io/xclang/reference/releases"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://docs.clice.io/xclang/reference/releases"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://docs.clice.io/zh/xclang/reference/releases"}]]},"headers":[],"relativePath":"xclang/reference/releases.md","filePath":"en/xclang/reference/releases.md","lastUpdated":1794509097000}'),r={name:"xclang/reference/releases.md"};function i(d,e,n,l,c,h){return a(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="releases" tabindex="-1">Releases <a class="header-anchor" href="#releases" aria-label="Permalink to &quot;Releases&quot;">​</a></h1><p>Every xclang release is published to GitHub releases, the clice conda channel, CMake <code>FetchContent</code>, and the clice Bazel registry. How to install xclang is in the <a href="./../guide/quick-start">quick start</a>, and what is inside an unpacked archive is in <a href="./layout">archive layout</a>.</p><h2 id="versions" tabindex="-1">Versions <a class="header-anchor" href="#versions" aria-label="Permalink to &quot;Versions&quot;">​</a></h2><p>Every release is tagged <code>&lt;llvm version&gt;.&lt;revision&gt;</code>. <code>23.1.2.1</code> is the first build of LLVM 23.1.2, and <code>23.1.2.2</code> is the second. The version identifies the upstream LLVM version and sorts consistently in conda, Bazel and CMake.</p><p>Published releases are never replaced. A fix or rebuild is always published as the next revision, and the release workflow refuses a version tag that already exists. A version and the <code>sha256</code> digests of its archives refer to the exact same bytes permanently. What changed in each release is recorded in the <a href="https://github.com/clice-io/xclang/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">CHANGELOG</a>.</p><h2 id="repacks" tabindex="-1">Repacks <a class="header-anchor" href="#repacks" aria-label="Permalink to &quot;Repacks&quot;">​</a></h2><p>When a change affects only the packaging, such as the Bazel module, the CMake package or the target config files, the release is a <em>repack</em>: the next revision reuses the compiler and runtimes of the previous release, byte for byte.</p><h2 id="channels" tabindex="-1">Channels <a class="header-anchor" href="#channels" aria-label="Permalink to &quot;Channels&quot;">​</a></h2><p>Each channel publishes the release under its <code>&lt;version&gt;</code> and provides a way to select a pinned release or the newest one:</p><table tabindex="0"><thead><tr><th>channel</th><th>what it publishes</th><th>pin a release</th><th>take the newest</th></tr></thead><tbody><tr><td><a href="https://github.com/clice-io/xclang/releases" target="_blank" rel="noreferrer">GitHub releases</a></td><td>all 17 release assets</td><td><code>releases/download/&lt;version&gt;</code></td><td><code>releases/latest</code>, whose <code>SHA256SUMS</code> names the version</td></tr><tr><td><a href="https://conda.clice.io" target="_blank" rel="noreferrer">conda.clice.io</a></td><td><code>xclang</code> per host and <code>noarch</code> <code>llvm-option-inc</code>, built from the release archives</td><td><code>xclang = &quot;&lt;version&gt;.*&quot;</code> (the package build number counts packaging fixes of that release)</td><td><code>xclang = &quot;*&quot;</code>, locked in <code>pixi.lock</code> until <code>pixi update</code></td></tr><tr><td>CMake FetchContent</td><td>the repository tag <code>&lt;version&gt;</code></td><td><code>GIT_TAG &lt;version&gt;</code></td><td><code>GIT_TAG latest</code>, a branch at the newest release tag</td></tr><tr><td><a href="https://bazel.clice.io" target="_blank" rel="noreferrer">bazel.clice.io</a></td><td>the <code>xclang</code> Bazel module, published after it builds and tests against the release archives</td><td><code>version = &quot;&lt;version&gt;&quot;</code></td><td>Bazel resolves the newest version requested across the dependency graph</td></tr></tbody></table><h2 id="assets" tabindex="-1">Assets <a class="header-anchor" href="#assets" aria-label="Permalink to &quot;Assets&quot;">​</a></h2><p>Every <a href="https://github.com/clice-io/xclang/releases" target="_blank" rel="noreferrer">GitHub release</a> contains the same 17 assets:</p><table tabindex="0"><thead><tr><th>asset</th><th>contents</th><th>size</th></tr></thead><tbody><tr><td><code>xclang-&lt;version&gt;-&lt;host&gt;.tar.xz</code></td><td>the toolchain archive, one per host, with all eight bundled targets (<a href="./layout">archive layout</a>)</td><td>about 100 MB</td></tr><tr><td><code>libclang-&lt;version&gt;-&lt;host&gt;.tar.xz</code></td><td>the static libraries and headers of <code>clang</code> and LLVM, one per host (<a href="./../features/libclang">libclang</a>)</td><td>about 265 MB</td></tr><tr><td><code>libclang-&lt;version&gt;-&lt;host&gt;-asan.tar.xz</code></td><td>the ASan-instrumented build of <code>libclang</code>, for Linux x64 and macOS arm64 (<a href="./../features/libclang#the-asan-build">the ASan build</a>)</td><td>about 200 MB</td></tr><tr><td><code>llvm-option-inc-&lt;version&gt;.tar.xz</code></td><td>the pre-generated option tables of <code>clang</code>, <code>lld</code>, <code>llvm-lib</code> and <code>llvm-dlltool</code> (<a href="./../features/libclang#the-option-tables">the option tables</a>)</td><td>about 200 KB</td></tr><tr><td><code>xclang-&lt;version&gt;.profdata</code></td><td>the PGO profile the release was built with (<a href="./../design/pgo">PGO</a>)</td><td>about 50 MB</td></tr><tr><td><code>SHA256SUMS</code></td><td>the <code>sha256</code> digest of every other asset in the release</td><td></td></tr></tbody></table><p>The six <code>&lt;host&gt;</code> triples are <code>x86_64-unknown-linux-gnu</code>, <code>aarch64-unknown-linux-gnu</code>, <code>x86_64-w64-mingw32</code>, <code>aarch64-w64-mingw32</code>, <code>aarch64-apple-darwin</code> and <code>x86_64-apple-darwin</code>.</p><h2 id="checking-a-download" tabindex="-1">Checking a Download <a class="header-anchor" href="#checking-a-download" aria-label="Permalink to &quot;Checking a Download&quot;">​</a></h2><p>The release workflow generates <code>SHA256SUMS</code> from the assets it uploads. Verify any downloaded asset against <code>SHA256SUMS</code> (pass <code>&lt;version&gt;</code> to <code>gh release download</code> for a specific release):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> release</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> download</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -R</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clice-io/xclang</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SHA256SUMS</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;llvm-option-inc-*&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sha256sum</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ignore-missing</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> SHA256SUMS</span></span></code></pre></div><p>The Bazel module checks every downloaded archive against the <code>sha256</code> digest pinned in its <code>versions.bzl</code>. CMake&#39;s <code>xclang.cmake</code> checks the toolchain archive against the <code>SHA256SUMS</code> file of the release. Pinning a digest in <code>versions.bzl</code> or in your own repository also protects against an archive and <code>SHA256SUMS</code> being replaced together on GitHub (<a href="./../design/roadmap#immutable-releases">immutable GitHub releases</a>).</p><h2 id="reproducible-builds" tabindex="-1">Reproducible Builds <a class="header-anchor" href="#reproducible-builds" aria-label="Permalink to &quot;Reproducible Builds&quot;">​</a></h2><p>Every release makes each host&#39;s archives twice, on two machines, and builds the <code>xclang</code> command twice, and compares them byte for byte: the archives are sorted, carry the commit&#39;s time and no owner, and are compressed in fixed blocks. A rebuild of a revision with its profile, <code>xclang-&lt;version&gt;.profdata</code>, is meant to give every archive again: every full rebuild starts a second full build, which checks that it does before the release is published. That is checked, not guaranteed: a bug of the compiler or linker that builds xclang can break it. A rebuild also needs GitHub&#39;s runners, as the programs keep some paths of the build and the macOS builds record the runner&#39;s Xcode SDK version.</p>`,20)])])}const u=t(r,[["render",i]]);export{g as __pageData,u as default};
